const b=await this.helpers.getBinaryDataBuffer(0,'data');
if(b.length<1024||b.subarray(4,8).toString()!=='ftyp')throw new Error('Invalid MP4 response');
function boxes(start,end){const a=[];for(let p=start;p+8<=end;){let z=b.readUInt32BE(p),head=8;const type=b.toString('ascii',p+4,p+8);if(z===1){if(p+16>end)throw new Error('Invalid MP4 size');z=Number(b.readBigUInt64BE(p+8));head=16;}if(z===0)z=end-p;if(!Number.isSafeInteger(z)||z<head||p+z>end)throw new Error('Invalid MP4 box');a.push({type,start:p+head,end:p+z});p+=z;}return a;}
function child(x,t){return boxes(x.start,x.end).find(v=>v.type===t);}
function timing(x){if(!x)throw new Error('Missing MP4 timing');const p=x.start,v=b[p],off=v===1?20:12,ts=b.readUInt32BE(p+off),d=v===1?Number(b.readBigUInt64BE(p+off+4)):b.readUInt32BE(p+off+4);if(!ts)throw new Error('Invalid MP4 timescale');return {timescale:ts,durationTicks:d,seconds:d/ts};}
const moov=boxes(0,b.length).find(x=>x.type==='moov');if(!moov)throw new Error('Missing MP4 moov');
const movie=timing(child(moov,'mvhd'));const tracks=boxes(moov.start,moov.end).filter(x=>x.type==='trak').map(t=>{const mdia=child(t,'mdia');if(!mdia)return null;const h=child(mdia,'hdlr'),kind=h?b.toString('ascii',h.start+8,h.start+12):'';const duration=timing(child(mdia,'mdhd'));const minf=child(mdia,'minf'),stbl=minf&&child(minf,'stbl'),stsz=stbl&&child(stbl,'stsz');return {kind,...duration,samples:stsz?b.readUInt32BE(stsz.start+8):null};}).filter(Boolean);
const video=tracks.find(t=>t.kind==='vide');if(!video||video.samples!==240||Math.abs(video.seconds-10)>1e-6||Math.abs(movie.seconds-10)>0.001||Math.abs(video.samples/video.seconds-24)>1e-6)throw new Error('Expected exactly 240 frames at 24fps and 10.000s MP4: '+JSON.stringify({movie,tracks}));
const items=$input.all();items[0].json={...items[0].json,verifiedVideoBytes:b.length,verifiedDurationSeconds:movie.seconds,verifiedVideoFrames:video.samples,verifiedFps:video.samples/video.seconds,verifiedTracks:tracks};return items;
